import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    sma_35 = close.rolling(35).mean()
    pos = np.zeros(len(close), dtype=int)
    state = 0
    entry = 0.0

    for t in range(1, len(close)):
        if state == 0:
            if close[t] > sma_35[t] and close[t-1] <= sma_35[t-1]:
                state, entry = 1, close[t]
        elif state == 1:
            if close[t] <= entry * (1 - 0.07) or close[t] >= entry * (1 + 0.08):
                state = 0
        pos[t] = state
    return pd.Series(pos, index=df.index)
