import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    sma = close.rolling(18).mean()
    pstd = close.rolling(18).std()
    upper = sma + 2.5 * pstd
    lower = sma - 2.5 * pstd

    pos = np.zeros(len(close), dtype=int)
    state = 0
    for t in range(len(close)):
        if state == 0:
            if close[t] > upper[t]:
                state = 1
            elif close[t] < lower[t]:
                state = -1
        elif state == 1:
            if close[t] <= sma[t]:
                state = 0
        elif state == -1:
            if close[t] >= sma[t]:
                state = 0
        pos[t] = state
    return pd.Series(pos, index=df.index)
