import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    fast = close.rolling(12).mean()
    pos = np.zeros(len(close), dtype=int)
    state = 0
    entry = 0.0
    peak = 0.0
    trough = 0.0

    for t in range(len(close)):
        if state == 0:
            if close[t] > fast[t] and close[t-1] <= fast[t-1]:
                state, entry = 1, close[t]
                peak = entry
                trough = entry
            elif close[t] < fast[t] and close[t-1] >= fast[t-1]:
                state, entry = -1, close[t]
                peak = entry
                trough = entry
        elif state == 1:
            if close[t] < peak * (1 - 0.05):
                state = 0
            else:
                peak = max(peak, close[t])
        elif state == -1:
            if close[t] > trough * (1 + 0.05):
                state = 0
            else:
                trough = min(trough, close[t])

        pos[t] = state

    return pd.Series(pos, index=df.index)
